window.REV_FLIP=window.REV_FLIP||{};window.REV_FLIP["hugging-face"]=[{"id":"hugging-face-f0001","card":"q-hugging-face-001-1-setup","sec":"hugging-face-s002","q":"Which three things can you reuse from the Hugging Face Hub?","a":"<ul>\n  <li>A <strong>tokenizer</strong>, which creates embeddings.</li>\n  <li>A <strong>model</strong>, the base checkpoint.</li>\n  <li><strong>Datasets</strong>, which are pre-labeled.</li>\n</ul>","hand":true},{"id":"hugging-face-f0002","card":"q-hugging-face-001-1-setup","sec":"hugging-face-s002","q":"What happens to Hugging Face models and datasets after the first download?","a":"<p>They are downloaded once and cached locally.</p>","hand":true},{"id":"hugging-face-f0003","card":"q-hugging-face-001-1-setup","sec":"hugging-face-s002","q":"Which packages does the Hugging Face course <code>requirements.txt</code> pin for the NLP libraries?","a":"<p><code>transformers==4.53.0</code>, <code>datasets==3.6.0</code>, <code>evaluate==0.4.4</code>, <code>sentencepiece==0.2.0</code>, <code>nltk==3.9.1</code> and <code>rouge_score==0.1.2</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>transformers==4.53.0\ndatasets==3.6.0\nsentencepiece==0.2.0\nevaluate==0.4.4\nnltk==3.9.1\nrouge_score==0.1.2</code></pre></div>","hand":true},{"id":"hugging-face-f0004","card":"q-hugging-face-001-1-setup","sec":"hugging-face-s002","q":"Which deep-learning frameworks does the Hugging Face course <code>requirements.txt</code> pin?","a":"<p>TensorFlow, PyTorch (CPU build), Keras and tf-keras.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Text</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>tensorflow==2.19.0\ntorch==2.7.0+cpu\nkeras==3.10.0\ntf-keras==2.19.0</code></pre></div>","hand":true},{"id":"hugging-face-f0005","card":"q-hugging-face-001-1-setup","sec":"hugging-face-s002","q":"How do you suppress Transformers warning messages at the top of a notebook?","a":"<p>Set the logging verbosity to error.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import transformers\ntransformers.logging.set_verbosity_error()</code></pre></div>","hand":true},{"id":"hugging-face-f0006","card":"q-hugging-face-002-2-question-answering","sec":"hugging-face-s003","q":"What is extractive question answering?","a":"<p>Given a <strong>context</strong> and a question, the model returns the span of the context that best answers the question.</p>","hand":true},{"id":"hugging-face-f0007","card":"q-hugging-face-002-2-question-answering","sec":"hugging-face-s003","q":"What is the flow of a question-answering model, from corpus to answer?","a":"<p>The corpus is tokenized and vectorized, and the question goes through the same steps. The model compares them, scores candidate answers, and returns the best one.</p>","hand":true},{"id":"hugging-face-f0008","card":"q-hugging-face-002-2-question-answering","sec":"hugging-face-s003","q":"Open Domain QA (ODQA) vs Closed Domain QA (CDQA): scope and corpus?","a":"<ul>\n  <li><strong>ODQA</strong>: any topic (like Google Search), with a very large corpus such as all of Wikipedia.</li>\n  <li><strong>CDQA</strong>: a specific domain (pharma, product FAQs), with a limited domain-specific corpus.</li>\n</ul>","hand":true},{"id":"hugging-face-f0009","card":"q-hugging-face-002-2-question-answering","sec":"hugging-face-s003","q":"Open Domain QA vs Closed Domain QA: model size, accuracy and cost?","a":"<ul>\n  <li><strong>ODQA</strong>: large model, lower accuracy, higher training and inference cost.</li>\n  <li><strong>CDQA</strong>: smaller model, higher accuracy, lower cost.</li>\n</ul>","hand":true},{"id":"hugging-face-f0010","card":"q-hugging-face-002-2-question-answering","sec":"hugging-face-s003","q":"What are the typical use cases of ODQA and CDQA?","a":"<p>ODQA fits public search. CDQA fits enterprise self-service and product Q&amp;A.</p>","hand":true},{"id":"hugging-face-f0011","card":"q-hugging-face-003-qa-pipeline","sec":"hugging-face-s004","q":"Which model does the Hugging Face question-answering example use?","a":"<p><code>deepset/minilm-uncased-squad2</code>, a BERT-based model trained on SQuAD 2.0. <code>pipeline(...)</code> downloads it to the local cache.</p>","hand":true},{"id":"hugging-face-f0012","card":"q-hugging-face-003-qa-pipeline","sec":"hugging-face-s004","q":"How do you create and call a question-answering pipeline?","a":"<p>Create it with the task name <code>\"question-answering\"</code> and a model, then pass a question and a context.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>quan_pipeline = pipeline(&quot;question-answering&quot;,\n                         model=&quot;deepset/minilm-uncased-squad2&quot;)\nanswer = quan_pipeline(question=&quot;How much of earth is land?&quot;,\n                       context=context)</code></pre></div>","hand":true},{"id":"hugging-face-f0013","card":"q-hugging-face-003-qa-pipeline","sec":"hugging-face-s004","q":"What fields does a Hugging Face question-answering pipeline return?","a":"<ul>\n  <li><code>score</code>: confidence from 0 to 1.</li>\n  <li><code>start</code> and <code>end</code>: character positions in the context.</li>\n  <li><code>answer</code>: the extracted text.</li>\n</ul>","hand":true},{"id":"hugging-face-f0014","card":"q-hugging-face-003-qa-pipeline","sec":"hugging-face-s004","q":"In the QA pipeline example, what was the output for \"How much of earth is land?\"","a":"<p>The answer was <code>29%</code> with a score of 0.955.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># {&#x27;score&#x27;: 0.955, &#x27;start&#x27;: 327, &#x27;end&#x27;: 330, &#x27;answer&#x27;: &#x27;29%&#x27;}</code></pre></div>","hand":true},{"id":"hugging-face-f0015","card":"q-hugging-face-003-qa-pipeline","sec":"hugging-face-s004","q":"What does a low score from the Hugging Face question-answering pipeline mean, and what should you do with it?","a":"<p>A low score signals a weak answer (0.26 for \"How are mountain ranges created?\"). Use the score as a threshold to filter out low-confidence answers before returning them to users.</p>","hand":true},{"id":"hugging-face-f0016","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"Why does question answering need a metric such as SQuAD instead of regular accuracy?","a":"<p>Regular accuracy often does not fit NLP outputs.</p>","hand":true},{"id":"hugging-face-f0017","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"What is the SQuAD metric and what does it report?","a":"<p>SQuAD (Stanford Question Answering Dataset) scores predicted answers against correct ones. It reports <strong>Exact Match</strong> and <strong>F1</strong>, per answer and for a whole dataset.</p>","hand":true},{"id":"hugging-face-f0018","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"Which package provides the SQuAD metric, and how do you load it?","a":"<p>The Hugging Face <code>evaluate</code> package.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from evaluate import load\nsquad_metric = load(&quot;squad_v2&quot;)</code></pre></div>","hand":true},{"id":"hugging-face-f0019","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"What are the steps of the QA evaluation workflow with the SQuAD metric?","a":"<p>Build an evaluation set (context, questions, correct answers), run it through the model, and compare the predictions with the correct answers using the metric.</p>","hand":true},{"id":"hugging-face-f0020","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"What dict format must predictions follow in the <code>squad_v2</code> metric?","a":"<p>Each prediction needs <code>prediction_text</code>, <code>id</code> and <code>no_answer_probability</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>predictions = [{&#x27;prediction_text&#x27;: predicted_answers[i],\n                &#x27;id&#x27;: str(i),\n                &#x27;no_answer_probability&#x27;: 0.}]</code></pre></div>","hand":true},{"id":"hugging-face-f0021","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"What dict format must references follow in the <code>squad_v2</code> metric?","a":"<p>Each reference needs <code>answers</code> (with <code>answer_start</code> and <code>text</code>) and an <code>id</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>references = [{&#x27;answers&#x27;: {&#x27;answer_start&#x27;: [1],\n                           &#x27;text&#x27;: [correct_answer]},\n               &#x27;id&#x27;: str(i)}]</code></pre></div>","hand":true},{"id":"hugging-face-f0022","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"How do you compute the SQuAD metric and read its F1?","a":"<p>Call <code>compute</code> with predictions and references, then read <code>f1</code> from the results.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>results = squad_metric.compute(predictions=predictions, references=references)\nprint(&quot;F1 is&quot;, results.get(&#x27;f1&#x27;), &quot; for answer :&quot;, predicted_answers[i])</code></pre></div>","hand":true},{"id":"hugging-face-f0023","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"With the correct answer \"Paris\", what F1 does the SQuAD metric give for \"Paris\", \"London\" and \"Paris is one of the best cities in the world\"?","a":"<ul>\n  <li>\"Paris\": 100.0 (exact match).</li>\n  <li>\"London\": 0.0 (no match).</li>\n  <li>\"Paris is one of the best cities in the world\": 22.22 (partial match, the word \"Paris\" is present).</li>\n</ul>","hand":true},{"id":"hugging-face-f0024","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"How does F1 behave for exact, absent and partial overlap in the SQuAD metric?","a":"<p>Exact match gives F1 = 100, no overlap gives 0, and partial overlap reflects token overlap.</p>","hand":true},{"id":"hugging-face-f0025","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"What keys does the cumulative SQuAD result contain?","a":"<ul>\n  <li><code>exact</code>: percent of exact matches (1 of 3 = 33.33).</li>\n  <li><code>f1</code>: average F1.</li>\n  <li><code>total</code>: number of answers evaluated.</li>\n  <li><code>HasAns_exact</code> and <code>HasAns_f1</code>: only the questions that have answers.</li>\n</ul>","hand":true},{"id":"hugging-face-f0026","card":"q-hugging-face-004-squad-metric","sec":"hugging-face-s005","q":"How do you evaluate all predictions together in the SQuAD metric?","a":"<p>Collect the predictions and references in lists, then compute once.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>cum_results = squad_metric.compute(predictions=cum_predictions, references=cum_references)</code></pre></div>","hand":true},{"id":"hugging-face-f0027","card":"q-hugging-face-005-3-text-summarization","sec":"hugging-face-s006","q":"What is text summarization?","a":"<p>It condenses a large text into a short summary that keeps the context and key points. Examples: documents, meeting transcripts, article and email previews.</p>","hand":true},{"id":"hugging-face-f0028","card":"q-hugging-face-005-3-text-summarization","sec":"hugging-face-s006","q":"Extractive vs abstractive summarization: how does each work?","a":"<ul>\n  <li><strong>Extractive</strong>: scores sentences and extracts the top ones verbatim.</li>\n  <li><strong>Abstractive</strong>: generates new human-like sentences that capture the gist.</li>\n</ul>","hand":true},{"id":"hugging-face-f0029","card":"q-hugging-face-005-3-text-summarization","sec":"hugging-face-s006","q":"Extractive vs abstractive summarization: completeness and complexity?","a":"<ul>\n  <li><strong>Extractive</strong>: some information may be left out. It is simpler to train and use.</li>\n  <li><strong>Abstractive</strong>: better at overall meaning. It is more complex to build.</li>\n</ul>","hand":true},{"id":"hugging-face-f0030","card":"q-hugging-face-005-3-text-summarization","sec":"hugging-face-s006","q":"Give an example of extractive and of abstractive summarization.","a":"<p>Extractive: a conversation summary that skips small talk. Abstractive: reducing large documents to concise new text.</p>","hand":true},{"id":"hugging-face-f0031","card":"q-hugging-face-005-3-text-summarization","sec":"hugging-face-s006","q":"What is BART?","a":"<p>Bidirectional Auto-Regressive Transformers, from Facebook. It is an encoder-decoder like T5, with a BERT-like encoder and a GPT-like decoder. It works for summarization, QA and generation.</p>","hand":true},{"id":"hugging-face-f0032","card":"q-hugging-face-006-summarization-pipeline","sec":"hugging-face-s007","q":"What is the default model of the Hugging Face summarization pipeline?","a":"<p><code>sshleifer/distilbart-cnn-12-6</code>, a DistilBART (distilled BART, <code>BartForConditionalGeneration</code>) with 12 encoder layers and 6 decoder layers.</p>","hand":true},{"id":"hugging-face-f0033","card":"q-hugging-face-006-summarization-pipeline","sec":"hugging-face-s007","q":"How do you create a summarization pipeline with length limits?","a":"<p>Use the task name <code>\"summarization\"</code> with <code>min_length</code> and <code>max_length</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>extractive_summarizer = pipeline(&quot;summarization&quot;,\n                                 min_length=10,\n                                 max_length=100)\nextractive_summary = extractive_summarizer(verbose_text)\nprint(extractive_summary[0].get(&quot;summary_text&quot;))</code></pre></div>","hand":true},{"id":"hugging-face-f0034","card":"q-hugging-face-006-summarization-pipeline","sec":"hugging-face-s007","q":"What do <code>min_length</code> and <code>max_length</code> do in the summarization pipeline, and what are their defaults?","a":"<p>They set the minimum and maximum number of tokens in the summary. The model defaults are 56 and 142. Tune them per use case.</p>","hand":true},{"id":"hugging-face-f0035","card":"q-hugging-face-006-summarization-pipeline","sec":"hugging-face-s007","q":"What should you do to real input text before summarizing it?","a":"<p>Clean up its formatting. The course code removes line feed characters first.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>verbose_text = verbose_text.replace(&quot;\\n&quot;, &quot;&quot;)</code></pre></div>","hand":true},{"id":"hugging-face-f0036","card":"q-hugging-face-006-summarization-pipeline","sec":"hugging-face-s007","q":"How do you inspect which checkpoint a summarization pipeline uses?","a":"<p>Print the model config of the pipeline.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>print(&quot;Checkpoint used:&quot;, extractive_summarizer.model.config)</code></pre></div>\n<p>It shows the model <code>sshleifer/distilbart-cnn-12-6</code>, architecture <code>BartForConditionalGeneration</code>, 12 encoder layers and 6 decoder layers.</p>","hand":true},{"id":"hugging-face-f0037","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"Why is ROUGE used for summaries instead of accuracy or F1?","a":"<p>Accuracy and F1 do not work well for summaries. ROUGE measures similarity between the summary and the reference text.</p>","hand":true},{"id":"hugging-face-f0038","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"What does ROUGE stand for and what range does it use?","a":"<p>Recall-Oriented Understudy for Gisting Evaluation. It is a family of metrics scored from 0.0 (no overlap) to 1.0 (perfect match).</p>","hand":true},{"id":"hugging-face-f0039","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"What do ROUGE-1, ROUGE-2, ROUGE-L and ROUGE-Lsum measure?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Metric</th><th>Measures</th></tr></thead>\n    <tbody>\n      <tr><td>ROUGE-1</td><td>Unigram overlap</td></tr>\n      <tr><td>ROUGE-2</td><td>Bigram overlap (phrase-level meaning)</td></tr>\n      <tr><td>ROUGE-L</td><td>Longest common subsequence</td></tr>\n      <tr><td>ROUGE-Lsum</td><td>Sentence-level ROUGE-L</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"hugging-face-f0040","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"How do you load and compute ROUGE with Hugging Face?","a":"<p>Load <code>\"rouge\"</code> from <code>evaluate</code>, then call <code>compute</code> with predictions and references.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>import evaluate\nrouge_evaluator = evaluate.load(&quot;rouge&quot;)\neval_results = rouge_evaluator.compute(predictions=predict_text, references=reference_text)</code></pre></div>","hand":true},{"id":"hugging-face-f0041","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"What ROUGE scores do you get when the summary is identical to the reference?","a":"<p>All scores are 1.0.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># {&#x27;rouge1&#x27;: 1.0, &#x27;rouge2&#x27;: 1.0, &#x27;rougeL&#x27;: 1.0, &#x27;rougeLsum&#x27;: 1.0}</code></pre></div>","hand":true},{"id":"hugging-face-f0042","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"What ROUGE scores do you get when the summary has no relation to the reference?","a":"<p>All scores are 0.0.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code># {&#x27;rouge1&#x27;: 0.0, &#x27;rouge2&#x27;: 0.0, &#x27;rougeL&#x27;: 0.0, &#x27;rougeLsum&#x27;: 0.0}</code></pre></div>","hand":true},{"id":"hugging-face-f0043","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"How do you score a summary against the original text with ROUGE, and what does about 0.6 mean?","a":"<p>Pass the summary as the prediction and the original text as the reference. Scores near 0.6 (rouge1 0.637 in the course demo) indicate a good summary there.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>eval_results = rouge_evaluator.compute(\n    predictions=[extractive_summary[0].get(&quot;summary_text&quot;)],\n    references=[verbose_text])</code></pre></div>","hand":true},{"id":"hugging-face-f0044","card":"q-hugging-face-007-rouge-score","sec":"hugging-face-s008","q":"How do you pick a ROUGE threshold, and what else is ROUGE used for?","a":"<p>Try examples to find the threshold for your use case, then track it on production inference. ROUGE also compares summarization models or configurations.</p>","hand":true},{"id":"hugging-face-f0045","card":"q-hugging-face-008-4-natural-language-generation","sec":"hugging-face-s009","q":"What is Natural Language Generation (NLG)?","a":"<p>It produces text meant to be indistinguishable from human writing, from a phrase to several paragraphs.</p>","hand":true},{"id":"hugging-face-f0046","card":"q-hugging-face-008-4-natural-language-generation","sec":"hugging-face-s009","q":"Which part of the transformer does NLG use, and which models?","a":"<p>The transformer <strong>decoder stack</strong>, in models such as GPT, BART and T5.</p>","hand":true},{"id":"hugging-face-f0047","card":"q-hugging-face-008-4-natural-language-generation","sec":"hugging-face-s009","q":"What are the use cases of NLG?","a":"<p>Content creation, chatbots and voice bots, translation, personalized emails, text reports from structured data, and product descriptions.</p>","hand":true},{"id":"hugging-face-f0048","card":"q-hugging-face-008-4-natural-language-generation","sec":"hugging-face-s009","q":"Which three NLG tasks does the Hugging Face course implement?","a":"<p>Content generation, conversation, and translation.</p>","hand":true},{"id":"hugging-face-f0049","card":"q-hugging-face-009-content-generation-gpt-2","sec":"hugging-face-s010","q":"What is special about GPT-2 for content generation?","a":"<p>It uses only the decoder stack and can produce several different continuations from the same seed sentence. The model name is <code>gpt2</code>.</p>","hand":true},{"id":"hugging-face-f0050","card":"q-hugging-face-009-content-generation-gpt-2","sec":"hugging-face-s010","q":"How do you create a text generator with GPT-2 in Hugging Face?","a":"<p>Use the <code>\"text-generation\"</code> pipeline with the <code>gpt2</code> model.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>text_generator = pipeline(&quot;text-generation&quot;, model=&quot;gpt2&quot;)</code></pre></div>","hand":true},{"id":"hugging-face-f0051","card":"q-hugging-face-009-content-generation-gpt-2","sec":"hugging-face-s010","q":"What do <code>num_return_sequences</code> and <code>max_new_tokens</code> do in a text-generation pipeline?","a":"<p><code>num_return_sequences</code> sets the number of separate outputs from the same input. <code>max_new_tokens</code> sets the maximum number of tokens produced beyond the input.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>synthetic_text = text_generator(input_text,\n                                num_return_sequences=3,\n                                max_new_tokens=50)</code></pre></div>","hand":true},{"id":"hugging-face-f0052","card":"q-hugging-face-009-content-generation-gpt-2","sec":"hugging-face-s010","q":"How do you make Hugging Face text generation reproducible?","a":"<p>Call <code>set_seed()</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>transformers.set_seed(1)</code></pre></div>","hand":true},{"id":"hugging-face-f0053","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"What does a conversational bot do?","a":"<p>It understands the user's intent and replies, can ask follow-up questions, and keeps conversation history as context.</p>","hand":true},{"id":"hugging-face-f0054","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"Which services do real chatbots combine?","a":"<p>Named Entity Recognition, Sentiment Analysis, Question Answering, and Text Generation.</p>","hand":true},{"id":"hugging-face-f0055","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"How does an order-status chatbot use several services?","a":"<p>The bot gets an order-status request, NER extracts the order number, a backend lookup runs, and text generation produces the reply.</p>","hand":true},{"id":"hugging-face-f0056","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"Which model does the Hugging Face chat example use?","a":"<p><code>Qwen/Qwen2.5-0.5B-Instruct</code>, a small instruction-tuned model that answers general questions and asks follow-ups.</p>","hand":true},{"id":"hugging-face-f0057","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"How do you build a chat pipeline from an explicit model and tokenizer?","a":"<p>Load both with the Auto classes, then pass them to a <code>\"text-generation\"</code> pipeline.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>model_name = &quot;Qwen/Qwen2.5-0.5B-Instruct&quot;\nconv_model = AutoModelForCausalLM.from_pretrained(model_name)\nconv_tokenizer = AutoTokenizer.from_pretrained(model_name)\nconv_pipeline = pipeline(&quot;text-generation&quot;,\n                         model=conv_model,\n                         tokenizer=conv_tokenizer)</code></pre></div>","hand":true},{"id":"hugging-face-f0058","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"How do you give a Hugging Face chatbot a persona?","a":"<p>Start the chat history with a <code>system</code> message.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>chat_history = [\n    {&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: &quot;You are a chatbot that engages in lively conversations&quot;},\n]</code></pre></div>","hand":true},{"id":"hugging-face-f0059","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"What is the structure of chat history, and which roles exist?","a":"<p>A list of <code>{\"role\", \"content\"}</code> dicts. The roles are <code>system</code> (persona and behavior), <code>user</code> and <code>assistant</code>.</p>","hand":true},{"id":"hugging-face-f0060","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"How does a multi-turn chat loop add the user turn and call the model?","a":"<p>Append the user message to the history, then call the pipeline with the full history.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>chat_history.append({&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: input})\nchat_outputs = conv_pipeline(chat_history, max_new_tokens=512)</code></pre></div>","hand":true},{"id":"hugging-face-f0061","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"Why append each assistant reply to the chat history?","a":"<p>It gives the bot context for follow-up questions. The loop appends the last message of the pipeline output to the history after every turn.</p>","hand":true},{"id":"hugging-face-f0062","card":"q-hugging-face-010-conversation-generation","sec":"hugging-face-s011","q":"How do you print a whole conversation after the chat loop?","a":"<p>Loop over the messages of the last pipeline output and print each one.</p>","hand":true},{"id":"hugging-face-f0063","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"What does machine translation do beyond word-for-word replacement, and which architectures are typical?","a":"<p>It translates with attention to context. Typical architectures are GPT-3 and T5.</p>","hand":true},{"id":"hugging-face-f0064","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"What are the challenges of machine translation?","a":"<p>Many languages and variants, and large models. Smaller custom models can be built for narrow cases.</p>","hand":true},{"id":"hugging-face-f0065","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"What are applications of machine translation?","a":"<p>Real-time speech translation, enterprise documents, multilingual customer service, and multilingual text analytics.</p>","hand":true},{"id":"hugging-face-f0066","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"Why use an explicit tokenizer and model instead of the translation pipeline?","a":"<p>It helps when a tokenizer and model combination is not supported by the pipeline.</p>","hand":true},{"id":"hugging-face-f0067","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"What is T5 and how does it know which task to perform?","a":"<p>T5 is <strong>text-to-text</strong>: one model does summarization, QA and translation. A <strong>task prefix</strong> on the input chooses the task. The model is <code>t5-base</code>.</p>","hand":true},{"id":"hugging-face-f0068","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"How do you load <code>t5-base</code> for translation?","a":"<p>Use the Seq2Seq model class and the matching tokenizer.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>model = AutoModelForSeq2SeqLM.from_pretrained(&quot;t5-base&quot;)\ntokenizer = AutoTokenizer.from_pretrained(&quot;t5-base&quot;)</code></pre></div>","hand":true},{"id":"hugging-face-f0069","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"How do you translate English to German with T5?","a":"<p>Prefix the text with the task, tokenize, call <code>generate</code>, and decode.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>inputs_german = tokenizer(&quot;translate English to German: &quot; + source_english,\n                          return_tensors=&quot;pt&quot;)\noutputs_german = model.generate(inputs_german[&quot;input_ids&quot;], max_length=40)\nprint(&quot;German:&quot;, tokenizer.decode(outputs_german[0], skip_special_tokens=True))</code></pre></div>","hand":true},{"id":"hugging-face-f0070","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"How do you switch T5 from German to French translation?","a":"<p>Use the same steps with a different task prefix.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>inputs_french = tokenizer(&quot;translate English to French: &quot; + source_english,\n                          return_tensors=&quot;pt&quot;)</code></pre></div>","hand":true},{"id":"hugging-face-f0071","card":"q-hugging-face-011-machine-translation","sec":"hugging-face-s012","q":"What do <code>return_tensors=\"pt\"</code>, <code>input_ids</code>, <code>max_length</code> and <code>skip_special_tokens=True</code> mean in the T5 example?","a":"<ul>\n  <li><code>return_tensors=\"pt\"</code>: return PyTorch tensors.</li>\n  <li><code>input_ids</code>: IDs into the embedding matrix.</li>\n  <li><code>max_length</code>: the output token limit.</li>\n  <li><code>skip_special_tokens=True</code>: strips <code>&lt;pad&gt;</code> and <code>&lt;/s&gt;</code> from the output.</li>\n</ul>","hand":true},{"id":"hugging-face-f0072","card":"q-hugging-face-012-5-transfer-learning-sentiment-model","sec":"hugging-face-s013","q":"What is transfer learning in Hugging Face?","a":"<p>Take a base model from the Hub, fine-tune it on a small task-specific dataset, and train a classifier (or sequence generator) on top. Encoder and decoder weights can be frozen or retrained.</p>","hand":true},{"id":"hugging-face-f0073","card":"q-hugging-face-012-5-transfer-learning-sentiment-model","sec":"hugging-face-s013","q":"What does transfer learning save?","a":"<p>It turns days of base training into minutes.</p>","hand":true},{"id":"hugging-face-f0074","card":"q-hugging-face-012-5-transfer-learning-sentiment-model","sec":"hugging-face-s013","q":"Which data, base checkpoint and model class does the sentiment transfer-learning example use?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Step</th><th>Artifact</th></tr></thead>\n    <tbody>\n      <tr><td>Data (poem verses labeled with sentiment)</td><td><code>poem_sentiment</code></td></tr>\n      <tr><td>Base checkpoint</td><td><code>distilbert-base-uncased</code></td></tr>\n      <tr><td>Transfer learning</td><td><code>TFAutoModelForSequenceClassification</code></td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"hugging-face-f0075","card":"q-hugging-face-013-5-1-load-the-dataset","sec":"hugging-face-s014","q":"In what format is the <code>poem_sentiment</code> dataset, and what is its schema?","a":"<p>It is in <strong>Apache Arrow</strong> format, downloaded and cached like models. The schema is <code>id</code>, <code>verse_text</code> and <code>label</code>.</p>","hand":true},{"id":"hugging-face-f0076","card":"q-hugging-face-013-5-1-load-the-dataset","sec":"hugging-face-s014","q":"What are the split sizes of <code>poem_sentiment</code>?","a":"<p>Train has 892 rows, validation 105 and test 104.</p>","hand":true},{"id":"hugging-face-f0077","card":"q-hugging-face-013-5-1-load-the-dataset","sec":"hugging-face-s014","q":"How do you load a dataset from the Hub?","a":"<p>Use <code>load_dataset</code> with the dataset name.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>from datasets import load_dataset\ndataset_name = &quot;poem_sentiment&quot;\npoem_sentiments = load_dataset(dataset_name)</code></pre></div>","hand":true},{"id":"hugging-face-f0078","card":"q-hugging-face-013-5-1-load-the-dataset","sec":"hugging-face-s014","q":"What are the labels of <code>poem_sentiment</code>, and how do you read them?","a":"<p>The labels are <code>negative</code>, <code>positive</code>, <code>no_impact</code> and <code>mixed</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>print(poem_sentiments[&quot;train&quot;].features.get(&quot;label&quot;).names)\n# [&#x27;negative&#x27;, &#x27;positive&#x27;, &#x27;no_impact&#x27;, &#x27;mixed&#x27;]</code></pre></div>","hand":true},{"id":"hugging-face-f0079","card":"q-hugging-face-013-5-1-load-the-dataset","sec":"hugging-face-s014","q":"How do you use your own data in Hugging Face training?","a":"<p>Convert it to a Hugging Face Dataset (with <code>Dataset.from_dict()</code>).</p>","hand":true},{"id":"hugging-face-f0080","card":"q-hugging-face-014-5-2-tokenize-and-encode","sec":"hugging-face-s015","q":"Which tokenizer class do you use for a Hugging Face checkpoint?","a":"<p>The tokenizer class that matches the checkpoint, such as <code>DistilBertTokenizer</code> for <code>distilbert-base-uncased</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>db_tokenizer = DistilBertTokenizer.from_pretrained(model_name)</code></pre></div>","hand":true},{"id":"hugging-face-f0081","card":"q-hugging-face-014-5-2-tokenize-and-encode","sec":"hugging-face-s015","q":"How do you tokenize a whole dataset with padding and truncation?","a":"<p>Define a tokenize function and apply it with <code>map(..., batched=True)</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>def tokenize(batch):\n    return db_tokenizer(batch[&quot;verse_text&quot;], padding=True, truncation=True)\nenc_poem_sentiment = poem_sentiments.map(tokenize, batched=True, batch_size=None)</code></pre></div>","hand":true},{"id":"hugging-face-f0082","card":"q-hugging-face-014-5-2-tokenize-and-encode","sec":"hugging-face-s015","q":"Which two features does tokenizing add to a dataset?","a":"<p><code>input_ids</code> and <code>attention_mask</code>.</p>","hand":true},{"id":"hugging-face-f0083","card":"q-hugging-face-014-5-2-tokenize-and-encode","sec":"hugging-face-s015","q":"What is <code>input_ids</code> and what do the values 101 and 102 mean?","a":"<p><code>input_ids</code> are IDs from the embedding matrix. They start with <code>101</code> (begin of string), end with <code>102</code> (end of string), and are right-padded with zeros to the max length.</p>","hand":true},{"id":"hugging-face-f0084","card":"q-hugging-face-014-5-2-tokenize-and-encode","sec":"hugging-face-s015","q":"What is <code>attention_mask</code>?","a":"<p>It is <code>1</code> for real tokens and <code>0</code> for padding. The model only attends to tokens with mask 1.</p>","hand":true},{"id":"hugging-face-f0085","card":"q-hugging-face-014-5-2-tokenize-and-encode","sec":"hugging-face-s015","q":"How do you get the number of labels from the dataset?","a":"<p>Take the length of the label names (4 for <code>poem_sentiment</code>).</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>labels = training_dataset.features.get(&quot;label&quot;)\nnum_labels = len(labels.names)  # 4</code></pre></div>","hand":true},{"id":"hugging-face-f0086","card":"q-hugging-face-015-5-3-model-architecture-and-freezing","sec":"hugging-face-s016","q":"What does loading a base checkpoint copy?","a":"<p>Its architecture, hyperparameters and weights, so nothing is built from scratch.</p>","hand":true},{"id":"hugging-face-f0087","card":"q-hugging-face-015-5-3-model-architecture-and-freezing","sec":"hugging-face-s016","q":"How do you load a sequence-classification model from a checkpoint, and what does <code>num_labels</code> do?","a":"<p>Use <code>TFAutoModelForSequenceClassification.from_pretrained</code>. <code>num_labels</code> sets the size of the new classification head.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sentiment_model = TFAutoModelForSequenceClassification.from_pretrained(\n    model_name, num_labels=num_labels)</code></pre></div>","hand":true},{"id":"hugging-face-f0088","card":"q-hugging-face-015-5-3-model-architecture-and-freezing","sec":"hugging-face-s016","q":"How do you inspect the configuration of the loaded model?","a":"<p>Call <code>get_config()</code>. The config shows 6 layers, 12 attention heads and dropout 0.1.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sentiment_model.get_config()</code></pre></div>","hand":true},{"id":"hugging-face-f0089","card":"q-hugging-face-015-5-3-model-architecture-and-freezing","sec":"hugging-face-s016","q":"What does freezing a layer mean?","a":"<p>Its weights are not updated in backpropagation, which keeps what the base model already learned.</p>","hand":true},{"id":"hugging-face-f0090","card":"q-hugging-face-015-5-3-model-architecture-and-freezing","sec":"hugging-face-s016","q":"How do you freeze and unfreeze the first layer of a Keras model?","a":"<p>Set its <code>trainable</code> attribute.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sentiment_model.layers[0].trainable = False\nsentiment_model.layers[0].trainable = True</code></pre></div>","hand":true},{"id":"hugging-face-f0091","card":"q-hugging-face-015-5-3-model-architecture-and-freezing","sec":"hugging-face-s016","q":"What are the layers and parameter counts of the DistilBERT sentiment model?","a":"<ul>\n  <li><code>distilbert</code> (TFDistilBertMainLayer): 66,362,880 params. This is the encoder, with most parameters.</li>\n  <li><code>pre_classifier</code> (Dense): 590,592 params.</li>\n  <li><code>classifier</code> (Dense): 3,076 params.</li>\n  <li>Total: 66,956,548 params (255.42 MB).</li>\n</ul>","hand":true},{"id":"hugging-face-f0092","card":"q-hugging-face-015-5-3-model-architecture-and-freezing","sec":"hugging-face-s016","q":"Besides freezing, how can you change the layers of a Keras model?","a":"<p>Layers can be added, inserted or removed through the <code>layers</code> object.</p>","hand":true},{"id":"hugging-face-f0093","card":"q-hugging-face-016-5-4-train","sec":"hugging-face-s017","q":"What are the steps to train the sentiment model?","a":"<p>Convert the datasets to TensorFlow with <code>to_tf_dataset</code>, <code>compile</code> (optimizer, loss, metrics), then <code>fit</code>.</p>","hand":true},{"id":"hugging-face-f0094","card":"q-hugging-face-016-5-4-train","sec":"hugging-face-s017","q":"How do you convert a Hugging Face dataset to a TensorFlow dataset?","a":"<p>Call <code>to_tf_dataset</code> with the tokenizer columns and label columns.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>tokenizer_columns = db_tokenizer.model_input_names\ntrain_dataset = training_dataset.to_tf_dataset(\n    columns=tokenizer_columns, label_cols=[&quot;label&quot;],\n    shuffle=True, batch_size=batch_size)</code></pre></div>","hand":true},{"id":"hugging-face-f0095","card":"q-hugging-face-016-5-4-train","sec":"hugging-face-s017","q":"Which batch size, shuffle setting and settings does the validation dataset use in the sentiment example?","a":"<p>Batch size 64. Training data is shuffled and validation data is not.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>batch_size = 64\nval_dataset = validation_dataset.to_tf_dataset(\n    columns=tokenizer_columns, label_cols=[&quot;label&quot;],\n    shuffle=False, batch_size=batch_size)</code></pre></div>","hand":true},{"id":"hugging-face-f0096","card":"q-hugging-face-016-5-4-train","sec":"hugging-face-s017","q":"How do you compile the sentiment model?","a":"<p>Use the Adam optimizer with learning rate 5e-5, sparse categorical cross-entropy loss with <code>from_logits=True</code>, and sparse categorical accuracy.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sentiment_model.compile(\n    optimizer=tf.keras.optimizers.Adam(learning_rate=5e-5),\n    loss=tf.keras.losses.SparseCategoricalCrossentropy(from_logits=True),\n    metrics=tf.metrics.SparseCategoricalAccuracy())</code></pre></div>","hand":true},{"id":"hugging-face-f0097","card":"q-hugging-face-016-5-4-train","sec":"hugging-face-s017","q":"How do you train the sentiment model, and what does training change?","a":"<p>Call <code>fit</code> with the training and validation datasets. Existing base parameters are updated based on the custom dataset.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>sentiment_model.fit(train_dataset, validation_data=val_dataset, epochs=5)</code></pre></div>","hand":true},{"id":"hugging-face-f0098","card":"q-hugging-face-016-5-4-train","sec":"hugging-face-s017","q":"What happened to accuracy over the five epochs of sentiment training?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Epoch</th><th>Train Acc</th><th>Val Loss</th><th>Val Acc</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>58.9%</td><td>0.909</td><td>65.7%</td></tr>\n      <tr><td>3</td><td>84.4%</td><td>0.486</td><td>86.7%</td></tr>\n      <tr><td>4</td><td>91.4%</td><td>0.485</td><td>86.7%</td></tr>\n      <tr><td>5</td><td>94.5%</td><td>0.554</td><td>82.9%</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"hugging-face-f0099","card":"q-hugging-face-016-5-4-train","sec":"hugging-face-s017","q":"What does the training result of the sentiment model show, and what helps?","a":"<p>Validation accuracy peaks at epochs 3 to 4 while training accuracy keeps rising. That is overfitting, so early stopping would help.</p>","hand":true},{"id":"hugging-face-f0100","card":"q-hugging-face-017-5-5-predict-with-the-custom-model","sec":"hugging-face-s018","q":"What do you handle yourself when predicting without a pipeline?","a":"<p>Pre-processing (tokenize, convert to tensors) and post-processing (labels from logits).</p>","hand":true},{"id":"hugging-face-f0101","card":"q-hugging-face-017-5-5-predict-with-the-custom-model","sec":"hugging-face-s018","q":"How do you turn data in any format into a Hugging Face Dataset?","a":"<p>Use <code>Dataset.from_dict()</code> with a dictionary shaped like the dataset.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>infer_dataset = Dataset.from_dict(infer_data)</code></pre></div>","hand":true},{"id":"hugging-face-f0102","card":"q-hugging-face-017-5-5-predict-with-the-custom-model","sec":"hugging-face-s018","q":"Is the <code>label</code> required in inference data, and is a <code>DatasetDict</code> required?","a":"<p>No to both. Labels are for comparison only, and you can use the dataset directly. A <code>DatasetDict</code> shows how to build one for training with your own data.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>ds_dict = DatasetDict()\nds_dict[&quot;infer&quot;] = infer_dataset</code></pre></div>","hand":true},{"id":"hugging-face-f0103","card":"q-hugging-face-017-5-5-predict-with-the-custom-model","sec":"hugging-face-s018","q":"How do you pre-process inference data and get predictions with the sentiment model?","a":"<p>Tokenize with the same function, convert to a TensorFlow dataset, then call <code>predict</code>.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>enc_dataset = ds_dict.map(tokenize, batched=True, batch_size=None)\ninfer_final_dataset = enc_dataset[&quot;infer&quot;].to_tf_dataset(\n    columns=tokenizer_columns, shuffle=True, batch_size=batch_size)\npredictions = sentiment_model.predict(infer_final_dataset)</code></pre></div>","hand":true},{"id":"hugging-face-f0104","card":"q-hugging-face-017-5-5-predict-with-the-custom-model","sec":"hugging-face-s018","q":"What does <code>predictions.logits</code> hold, and how do you get the predicted class?","a":"<p>It holds raw class scores per input. <code>np.argmax</code> over axis 1 picks the top class.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>pred_label_ids = np.argmax(predictions.logits, axis=1)</code></pre></div>","hand":true},{"id":"hugging-face-f0105","card":"q-hugging-face-017-5-5-predict-with-the-custom-model","sec":"hugging-face-s018","q":"How do you map predicted ids back to label names?","a":"<p>Index <code>labels.names</code> with the predicted id.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>for i in range(len(pred_label_ids)):\n    print(&quot;Poem =&quot;, infer_data[&quot;verse_text&quot;][i],\n          &quot; Predicted=&quot;, labels.names[pred_label_ids[i]],\n          &quot; True-Label=&quot;, labels.names[infer_data[&quot;label&quot;][i]])</code></pre></div>","hand":true},{"id":"hugging-face-f0106","card":"q-hugging-face-017-5-5-predict-with-the-custom-model","sec":"hugging-face-s018","q":"How did the custom sentiment model do on the two sample verses?","a":"<p>The first sample was right and the second was wrong (predicted positive, true label negative), so more data or epochs would help.</p>","hand":true},{"id":"hugging-face-f0107","card":"q-hugging-face-018-inference-challenges","sec":"hugging-face-s019","q":"What are the challenges of serving Hugging Face models in production?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Challenge</th><th>Details</th></tr></thead>\n    <tbody>\n      <tr><td>Model fit</td><td>Checkpoints are trained for specific data, so often need transfer learning</td></tr>\n      <tr><td>Model size</td><td>Can exceed 1B parameters, needing a large memory pool for weights plus temporary variables</td></tr>\n      <tr><td>Compute</td><td>Heavy math through encoder/decoder. GPUs parallelize but cost more</td></tr>\n      <tr><td>Latency</td><td>Inference can take seconds</td></tr>\n      <tr><td>Scaling</td><td>Many concurrent requests are hard to serve from one deployment</td></tr>\n      <tr><td>Cost</td><td>Cost per inference is high for unoptimized transformers</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"hugging-face-f0108","card":"q-hugging-face-018-inference-challenges","sec":"hugging-face-s019","q":"Why is model size a challenge for transformer inference?","a":"<p>Models can exceed 1B parameters, so they need a large memory pool for weights plus temporary variables.</p>","hand":true},{"id":"hugging-face-f0109","card":"q-hugging-face-018-inference-challenges","sec":"hugging-face-s019","q":"Why is compute a challenge for transformer inference?","a":"<p>Heavy math runs through the encoder and decoder. GPUs parallelize it but cost more.</p>","hand":true},{"id":"hugging-face-f0110","card":"q-hugging-face-019-when-to-customize-a-pretrained-model","sec":"hugging-face-s020","q":"When should you customize a pretrained model?","a":"<ul>\n  <li>Accuracy is low out of the box.</li>\n  <li>The domain has its own vocabulary or grammar (medical, legal, tweets, regional variants).</li>\n  <li>You want a smaller size by cutting encoder and decoder layers. Then check that performance still holds.</li>\n</ul>","hand":true},{"id":"hugging-face-f0111","card":"q-hugging-face-019-when-to-customize-a-pretrained-model","sec":"hugging-face-s020","q":"What is the guidance for transfer learning data and changes?","a":"<p>Use small, specific datasets that cover all scenarios equally, with accurately labeled, high-quality data. Change the architecture one step at a time and check the impact.</p>","hand":true},{"id":"hugging-face-f0112","card":"q-hugging-face-019-when-to-customize-a-pretrained-model","sec":"hugging-face-s020","q":"What should you do after transfer learning when the model runs in production?","a":"<p>Validate across scenarios, monitor production for drift and bias, and retrain as new data arrives.</p>","hand":true},{"id":"hugging-face-f0113","card":"q-hugging-face-020-model-compression","sec":"hugging-face-s021","q":"What is the goal of model compression, and what are the two routes?","a":"<p>The goal is a smaller trained model for production. The routes are fewer layers, nodes and parameters, or smaller storage types (FLOAT32 to integers). Both cut math operations, memory and compute.</p>","hand":true},{"id":"hugging-face-f0114","card":"q-hugging-face-020-model-compression","sec":"hugging-face-s021","q":"What is quantization?","a":"<p>It converts floats to smaller types such as integers. Most frameworks support it out of the box.</p>","hand":true},{"id":"hugging-face-f0115","card":"q-hugging-face-020-model-compression","sec":"hugging-face-s021","q":"What is pruning?","a":"<p>It removes selected nodes and connections.</p>","hand":true},{"id":"hugging-face-f0116","card":"q-hugging-face-020-model-compression","sec":"hugging-face-s021","q":"What is low rank approximation?","a":"<p>It reduces data dimensions by dropping unneeded information.</p>","hand":true},{"id":"hugging-face-f0117","card":"q-hugging-face-020-model-compression","sec":"hugging-face-s021","q":"What is knowledge distillation?","a":"<p>An advanced technique that shrinks the model while retaining learned knowledge. Examples: DistilBERT and DistilBART.</p>","hand":true},{"id":"hugging-face-f0118","card":"q-hugging-face-020-model-compression","sec":"hugging-face-s021","q":"What is neural architecture search?","a":"<p>It finds the best architecture for a problem. It is compute intensive.</p>","hand":true},{"id":"hugging-face-f0119","card":"q-hugging-face-020-model-compression","sec":"hugging-face-s021","q":"What should you do after compressing a model, and which techniques come first?","a":"<p>Retest on the original test and validation data. Start with quantization and pruning before the advanced options, which need more time and expertise.</p>","hand":true},{"id":"hugging-face-f0120","card":"q-hugging-face-021-serving-multiple-models","sec":"hugging-face-s022","q":"What are the three patterns for serving multiple models?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Pattern</th><th>How it works</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td>Chain (sequential)</td><td>Output of one model feeds the next</td><td>Chatbot: intent detection, then NER, then QA</td></tr>\n      <tr><td>Parallel (independent)</td><td>Same input goes to all models at once, outputs are collected</td><td>Review analysis: sentiment, topic extraction, obscenity detection</td></tr>\n      <tr><td>Alternate (conditional)</td><td>Condition picks one model</td><td>Language detector picks the matching translator into English</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"hugging-face-f0121","card":"q-hugging-face-021-serving-multiple-models","sec":"hugging-face-s022","q":"What is the chain pattern for serving multiple models?","a":"<p>The output of one model feeds the next, such as intent detection, then NER, then QA in a chatbot.</p>","hand":true},{"id":"hugging-face-f0122","card":"q-hugging-face-021-serving-multiple-models","sec":"hugging-face-s022","q":"What is the parallel pattern for serving multiple models?","a":"<p>The same input goes to all models at once and the outputs are collected. Example: review analysis with sentiment, topic extraction and obscenity detection.</p>","hand":true},{"id":"hugging-face-f0123","card":"q-hugging-face-021-serving-multiple-models","sec":"hugging-face-s022","q":"What is the alternate pattern for serving multiple models?","a":"<p>A condition picks one model. Example: a language detector picks the matching translator into English.</p>","hand":true},{"id":"hugging-face-f0124","card":"q-hugging-face-021-serving-multiple-models","sec":"hugging-face-s022","q":"What are best practices for serving multiple models?","a":"<ul>\n  <li>Test the models together as one solution.</li>\n  <li>Parallelize where possible to cut latency.</li>\n  <li>Validate that one model's output suits the next.</li>\n  <li>Exit chains early when intent confidence is too low.</li>\n  <li>Scale each model independently.</li>\n  <li>Measure end-to-end latency.</li>\n</ul>","hand":true},{"id":"hugging-face-f0125","card":"q-hugging-face-022-models-used","sec":"hugging-face-s023","q":"Which Hugging Face model does the course use for each task?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Model</th><th>Task</th><th>Notes</th></tr></thead>\n    <tbody>\n      <tr><td><code>deepset/minilm-uncased-squad2</code></td><td>Question answering</td><td>BERT-based, SQuAD 2.0</td></tr>\n      <tr><td><code>sshleifer/distilbart-cnn-12-6</code></td><td>Summarization</td><td>DistilBART</td></tr>\n      <tr><td><code>gpt2</code></td><td>Text generation</td><td>OpenAI GPT-2</td></tr>\n      <tr><td><code>Qwen/Qwen2.5-0.5B-Instruct</code></td><td>Chatbot</td><td>Instruction-tuned</td></tr>\n      <tr><td><code>t5-base</code></td><td>Translation</td><td>Google T5, task prefix</td></tr>\n      <tr><td><code>distilbert-base-uncased</code></td><td>Sentiment (fine-tuned)</td><td>DistilBERT</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"hugging-face-f0126","card":"q-hugging-face-022-models-used","sec":"hugging-face-s023","q":"Which model does the course use for text generation, and which for translation?","a":"<p><code>gpt2</code> (OpenAI GPT-2) for text generation and <code>t5-base</code> (Google T5, with a task prefix) for translation.</p>","hand":true},{"id":"hugging-face-f0127","card":"q-hugging-face-022-models-used","sec":"hugging-face-s023","q":"Which model is fine-tuned for sentiment in the course?","a":"<p><code>distilbert-base-uncased</code> (DistilBERT).</p>","hand":true},{"id":"hugging-face-f0128","card":"q-hugging-face-023-pipeline-task-names","sec":"hugging-face-s024","q":"What are the pipeline task names in Hugging Face?","a":"<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Task</th><th>Name</th></tr></thead>\n    <tbody>\n      <tr><td>Question answering</td><td><code>\"question-answering\"</code></td></tr>\n      <tr><td>Summarization</td><td><code>\"summarization\"</code></td></tr>\n      <tr><td>Text generation</td><td><code>\"text-generation\"</code></td></tr>\n      <tr><td>Translation</td><td>Seq2Seq model with task prefix</td></tr>\n      <tr><td>Sentiment</td><td><code>\"sentiment-analysis\"</code> or custom trained</td></tr>\n    </tbody>\n  </table>\n</div>","hand":true},{"id":"hugging-face-f0129","card":"q-hugging-face-023-pipeline-task-names","sec":"hugging-face-s024","q":"Which pipeline name handles translation in the course?","a":"<p>There is no dedicated pipeline name. Translation uses a Seq2Seq model with a task prefix.</p>","hand":true},{"id":"hugging-face-f0130","card":"q-hugging-face-024-evaluation-metrics","sec":"hugging-face-s025","q":"Which Hugging Face metric do you use for QA, and how do you load it?","a":"<p>SQuAD v2 (Exact Match and F1). Load it with <code>evaluate.load(\"squad_v2\")</code>.</p>","hand":true},{"id":"hugging-face-f0131","card":"q-hugging-face-024-evaluation-metrics","sec":"hugging-face-s025","q":"Which Hugging Face metric do you use for summarization, and how do you load it?","a":"<p>ROUGE (1, 2, L, Lsum). Load it with <code>evaluate.load(\"rouge\")</code>.</p>","hand":true},{"id":"hugging-face-f0132","card":"q-hugging-face-024-evaluation-metrics","sec":"hugging-face-s025","q":"Which metric does the course use for classification training?","a":"<p>Sparse categorical accuracy, from <code>tf.metrics</code>.</p>","hand":true},{"id":"hugging-face-f0133","card":"q-hugging-face-025-three-api-levels","sec":"hugging-face-s026","q":"What are the three API levels of Hugging Face Transformers?","a":"<ul>\n  <li><strong>High-level</strong>: the Pipeline API.</li>\n  <li><strong>Mid-level</strong>: <code>AutoModel</code> plus <code>AutoTokenizer</code>.</li>\n  <li><strong>Fine-tuning</strong>: <code>TFAutoModelForSequenceClassification</code>.</li>\n</ul>","hand":true},{"id":"hugging-face-f0134","card":"q-hugging-face-025-three-api-levels","sec":"hugging-face-s026","q":"What does the high-level Pipeline API look like?","a":"<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>result = pipeline(&quot;task-name&quot;, model=&quot;model-name&quot;)(input)</code></pre></div>","hand":true},{"id":"hugging-face-f0135","card":"q-hugging-face-025-three-api-levels","sec":"hugging-face-s026","q":"How do you use the mid-level Hugging Face API?","a":"<p>Load a tokenizer and a model with the Auto classes.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>tokenizer = AutoTokenizer.from_pretrained(&quot;model-name&quot;)\nmodel = AutoModel.from_pretrained(&quot;model-name&quot;)</code></pre></div>","hand":true},{"id":"hugging-face-f0136","card":"q-hugging-face-025-three-api-levels","sec":"hugging-face-s026","q":"How do you fine-tune with the Hugging Face fine-tuning API?","a":"<p>Load the sequence-classification model with <code>num_labels</code>, compile, then fit.</p>\n<div class=\"code-tabs flip-code\"><div class=\"tabbar\"><div class=\"tablist\"><button type=\"button\" class=\"tab\" aria-selected=\"true\">Python</button></div><button type=\"button\" class=\"code-copy\" title=\"Copy this code\" aria-label=\"Copy this code\">Copy</button></div><pre><code>model = TFAutoModelForSequenceClassification.from_pretrained(&quot;model-name&quot;, num_labels=N)\nmodel.compile(...)\nmodel.fit(train_dataset, validation_data=val_dataset, epochs=E)</code></pre></div>","hand":true}];
